with a as(select * from public.authors where open_library_id=any(array['OL28641A','OL863535A','OL934457A']::text[]) or id=any(array[187]::bigint[])) select jsonb_build_object('checked_at',clock_timestamp(),'authors',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from a t),'author_corpora',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where author_id in(select id from a)),'isbn_matches',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.editions t where regexp_replace(coalesce(isbn_13,''),'[-[:space:]]','','g')=any(array['9789061202509','9789032004767']::text[])),'source_work_matches',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where open_library_id=any(array['OL59705W','OL267619W']::text[])),'title_matches',(select coalesce(jsonb_agg(jsonb_build_object('relation','works','row',to_jsonb(t))),'[]') from public.works t where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['thenumberofthebeast','hetgetalvanhetbeest','asterixencorse','asterixopcorsica']::text[])),'edition_title_matches',(select coalesce(jsonb_agg(jsonb_build_object('relation','editions','row',to_jsonb(t))),'[]') from public.editions t where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['thenumberofthebeast','hetgetalvanhetbeest','asterixencorse','asterixopcorsica']::text[])),'reserved_test_ranges',jsonb_build_object('works',(select count(*) from public.works where id between 987128001 and 987128999),'editions',(select count(*) from public.editions where id between 987228001 and 987228999),'authors',(select count(*) from public.authors where id between 987328001 and 987328999))) as preflight;
